import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { productsAPI } from '../utils/api';
import ProductCard from '../components/ProductCard';
import { Shield, BarChart2, Zap, ArrowRight, Star } from 'lucide-react';
import './Home.css';

export default function Home() {
  const [topProducts, setTopProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    productsAPI.getTop(6)   // ✅ use correct API
      .then(res => {
        setTopProducts(res.data);
      })
      .catch(err => console.error(err))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="home page-enter">
      {/* Hero */}
      <section className="hero">
        <div className="hero-glow" />
        <div className="container hero-inner">
          <div className="hero-badge">
            <Shield size={13} /> Trustworthy AI Recommendations
          </div>
          <h1 className="hero-title">
            Discover Software You Can
            <span className="hero-accent"> Actually Trust</span>
          </h1>
          <p className="hero-sub">
            Our system scores every product using collaborative filtering,
            content-based similarity, and a trust model.
          </p>
          <div className="hero-actions">
            <Link to="/products" className="btn btn-primary">
              Browse Products <ArrowRight size={16} />
            </Link>
          </div>
        </div>
      </section>

      {/* How it works */}
      <section className="how-section container">
        <h2 className="section-title">How the Trust Engine Works</h2>
        <div className="grid-3 how-grid">
          {[
            {
              icon: <Star size={22} />,
              title: 'Product Trust',
              desc: 'Based on ratings, reviews, and consistency.',
            },
            {
              icon: <Shield size={22} />,
              title: 'User Trust',
              desc: 'Measures reviewer credibility.',
            },
            {
              icon: <Zap size={22} />,
              title: 'Hybrid Recommendations',
              desc: 'Combines collaborative + content filtering.',
            },
          ].map(h => (
            <div key={h.title} className="how-card card">
              <div className="how-icon">{h.icon}</div>
              <h3 className="how-title">{h.title}</h3>
              <p className="how-desc">{h.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Top trusted products */}
      <section className="products-section container">
        <div className="section-header">
          <div>
            <h2 className="section-title">Top Trusted Products</h2>
          </div>
          <Link to="/products" className="btn btn-ghost">
            View all <ArrowRight size={14} />
          </Link>
        </div>

        {loading ? (
          <div className="loading-center">
            <div className="spinner" />
          </div>
        ) : (
          <div className="grid-3">
            {topProducts.map((p, i) => (
              <ProductCard key={i} product={p} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
